        fields.forEach((field) => {
          const input = document.getElementById(field.id);

          input.addEventListener("blur", () => {
            setFieldError(input, getFieldError(field, input.value));
          });

          input.addEventListener("input", () => {
            if (input.getAttribute("aria-invalid") === "true") {
              setFieldError(input, getFieldError(field, input.value));
            }

            status.textContent = "";
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "";

          const invalidInputs = fields
            .map((field) => {
              const input = document.getElementById(field.id);
              const error = getFieldError(field, input.value);
              setFieldError(input, error);
              return error ? input : null;
            })
            .filter(Boolean);

          if (invalidInputs.length > 0) {
            invalidInputs[0].focus();
            return;
          }

          form.reset();
          fields.forEach((field) => {
            setFieldError(document.getElementById(field.id), "");
          });
          status.textContent = "Thanks. Your support request contact details are ready to submit.";
        });
      }

      document.getElementById("root").innerHTML = App();
      initContactForm();
    </script>
