          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "(555) 123-4567",
          helper: "Optional. Use 10 digits, with or without spaces, dashes, or parentheses.",
          error: "Enter a valid phone number, such as (555) 123-4567."
