   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const fields = [
         {
           id: "fullName",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           placeholder: "Jordan Lee",
           error: "Enter your full name."
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           placeholder: "jordan@example.com",
           error: "Enter a valid email address, such as jordan@example.com."
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           placeholder: "(555) 123-4567",
           helper: "Optional. Use 10 digits, with or without spaces, dashes, or parentheses.",
           error: "Enter a valid phone number, such as (555) 123-4567."
         }
       ];

       function Field({ id, label, type, autocomplete, required, placeholder, helper, error }) {
         const helperId = helper ? `${id}-helper` : "";
         const errorId = `${id}-error`;
         const describedBy = [helperId, errorId].filter(Boolean).join(" ");

         return `
           <div class="form-field" data-field="${id}">
             <label for="${id}">
               ${label}${required ? '<span class="required-marker" aria-hidden="true">*</span>' : ""}
             </label>
             <input
               id="${id}"
               name="${id}"
               type="${type}"
               autocomplete="${autocomplete}"
               ${required ? "required aria-required=\"true\"" : ""}
               aria-invalid="false"
               aria-describedby="${describedBy}"
               placeholder="${placeholder}"
             />
             ${helper ? `<p class="helper-text" id="${helperId}">${helper}</p>` : ""}
             <p class="error-message" id="${errorId}">${error}</p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="form-panel" aria-labelledby="form-heading">
             <h2 class="form-heading" id="form-heading">Tell us how to reach you</h2>
             <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
             <form class="contact-form" id="support-form" novalidate>
               ${fields.map(Field).join("")}
               <button class="submit-button" type="submit">Submit support request</button>
               <p class="form-status" id="form-status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function App() {
         return `
           <main class="page-shell" id="main-content">
             <article class="support-card">
               <section class="support-intro" aria-labelledby="page-title">
                 <div>
                   <p class="eyebrow">Support center</p>
                   <h1 id="page-title">Get help from our team</h1>
                   <p class="intro-copy">
                     Share your contact details and a product specialist will route your request to the right support expert.
                   </p>
                 </div>
                 <p class="response-note">
                   <strong>Fast follow-up</strong>
                   We typically respond within one business day.
                 </p>
               </section>
               ${ContactForm()}
             </article>
           </main>
         `;
       }

       function validateEmail(value) {
         return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
       }

       function validatePhone(value) {
         if (!value) {
           return true;
         }

         const digits = value.replace(/\D/g, "");
         return digits.length === 10;
       }

       function getFieldError(field, value) {
         const trimmedValue = value.trim();

         if (field.required && !trimmedValue) {
           return field.error;
         }

         if (field.id === "email" && trimmedValue && !validateEmail(trimmedValue)) {
           return field.error;
         }

         if (field.id === "phone" && !validatePhone(trimmedValue)) {
           return field.error;
         }

         return "";
       }

       function setFieldError(input, message) {
         const wrapper = input.closest(".form-field");
         const errorMessage = document.getElementById(`${input.id}-error`);

         wrapper.classList.toggle("has-error", Boolean(message));
         input.setAttribute("aria-invalid", message ? "true" : "false");
         errorMessage.textContent = message;
       }

       function initContactForm() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         fields.forEach((field) => {
           const input = document.getElementById(field.id);

           input.addEventListener("blur", () => {
             setFieldError(input, getFieldError(field, input.value));
           });

           input.addEventListener("input", () => {
             if (input.getAttribute("aria-invalid") === "true") {
               setFieldError(input, getFieldError(field, input.value));
             }

             status.textContent = "";
           });
         });

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const invalidInputs = fields
             .map((field) => {
               const input = document.getElementById(field.id);
               const error = getFieldError(field, input.value);
               setFieldError(input, error);
               return error ? input : null;
             })
             .filter(Boolean);

           if (invalidInputs.length > 0) {
             invalidInputs[0].focus();
             return;
           }

           form.reset();
           fields.forEach((field) => {
             setFieldError(document.getElementById(field.id), "");
           });
           status.textContent = "Thanks. Your support request contact details are ready to submit.";
         });
       }

       document.getElementById("root").innerHTML = App();
       initContactForm();
     </script>
   </body>
